// Regenerates packages/game/src/abi.ts from the Foundry build output.
import { readFileSync, writeFileSync } from "node:fs";

const read = (n) => JSON.parse(readFileSync(`contracts/out/${n}.sol/${n}.json`, "utf8")).abi;
const out =
  "// Generated by scripts/export-abi.mjs. Do not edit.\n" +
  `export const potEscrowAbi = ${JSON.stringify(read("PotEscrow"), null, 2)} as const;\n\n` +
  `export const testTokenAbi = ${JSON.stringify(read("TestToken"), null, 2)} as const;\n\n` +
  `export const jinxEscrowAbi = ${JSON.stringify(read("JinxEscrow"), null, 2)} as const;\n`;
writeFileSync("packages/game/src/abi.ts", out);
console.log("wrote packages/game/src/abi.ts");
